#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef long double ld;
typedef complex<ll> point;
#define F first
#define S second

template<typename T, typename C = T>
struct min_cost_flow
{
	struct edge
	{
		int src, dst;
		T cap, flow;
		C cost;
		int rev;
	};

	int n;
	vector<vector<edge>> adj;

	min_cost_flow(int n) : n(n), adj(n) {}

	void add_edge(int src, int dst, T cap, C cost)
	{
		adj[src].push_back({ src, dst, cap, 0, cost, (int) adj[dst].size() });
		if (src == dst)
			adj[src].back().rev++;
		adj[dst].push_back({ dst, src, 0, 0, -cost, (int) adj[src].size() - 1 });
	}

	const C oo = numeric_limits<C>::max();

	vector<C> dist, pot;
	vector<edge*> prev;

	bool dijkstra(int s, int t)
	{
		dist.assign(n, oo);
		prev.assign(n, nullptr);
		dist[s] = 0;

		using pci = pair<C, int>;
		priority_queue<pci, vector<pci>, greater<pci>> pq;
		pq.push({ 0, s });

		while (!pq.empty())
		{
			C d; int u;
			tie(d, u) = pq.top();
			pq.pop();

			if (d != dist[u])
				continue;

			for (auto &e : adj[u])
				if (e.flow < e.cap
						&& dist[e.dst] > dist[u] + e.cost + pot[u] - pot[e.dst])
				{
					dist[e.dst] = dist[u] + e.cost + pot[u] - pot[e.dst];
					prev[e.dst] = &e;
					pq.push({ dist[e.dst], e.dst });
				}
		}

		return dist[t] < oo;
	}

	pair<T, C> max_flow(int s, int t)
	{
		T flow = 0;
		C cost = 0;

		pot.assign(n, 0);
		while (dijkstra(s, t))
		{
			for (int u = 0; u < n; ++u)
				if (dist[u] < oo)
					pot[u] += dist[u];

			T delta = numeric_limits<T>::max();
			for (edge *e = prev[t]; e != nullptr; e = prev[e->src])
				delta = min(delta, e->cap - e->flow);

			flow += delta;
			for (edge *e = prev[t]; e != nullptr; e = prev[e->src])
			{
				e->flow += delta;
				adj[e->dst][e->rev].flow -= delta;
				cost += delta * e->cost;
			}
		}

		return {flow, cost};
	}
};


int main()
{
	#ifdef DGC
		//freopen("a.txt", "r", stdin);
		//freopen("b.txt", "w", stdout);
	#endif

	ios_base::sync_with_stdio(0), cin.tie(0);

	int n, m, k, c, d;
	cin >> n >> m >> k >> c >> d;
	vector<int> mk(n+1);
	for (int i = 0, x; i < k; ++i)
		cin >> x, ++mk[x];

	int sink = (k+1)*n*n+1;
	min_cost_flow<int, int> mcf(sink+1);

	for (int i = 0, u, v; i < m; ++i)
	{
		cin >> u >> v;
		for (int t = 0; t < k*n; ++t)
			for (int j = 1; j <= 1+2*k; j += 2)
			{
				mcf.add_edge(t*n+u, (t+1)*n+v, 1, j*d+c);
				mcf.add_edge(t*n+v, (t+1)*n+u, 1, j*d+c);
			}
	}

	for (int t = 0; t < k*n; ++t)
		for (int j = 1; j <= n; ++j)
			mcf.add_edge(t*n+j, (t+1)*n+j, k, c);

	for (int t = 0; t <= k*n; ++t)
		mcf.add_edge(t*n+1, sink, k, 0);

	for (int i = 1; i <= n; ++i)
		if (mk[i] > 0)
			mcf.add_edge(0, i, mk[i], 0);

	cout << mcf.max_flow(0, sink).S << "\n";

	return 0;
}

